mapper.update:
UPDATE mrp_stock_risk
SET resolved_at=CURRENT_TIMESTAMP(3), resolved_by=#{resolvedBy}, resolution_code=#{resolutionCode}
WHERE batch_id=#{batchId} AND run_id=#{runId} AND resolved_at IS NULL

mapper.select:
SELECT * FROM mrp_stock_risk WHERE batch_id=#{batchId} AND resolved_at IS NULL
AND run_id=#{runId}
ORDER BY FIELD(risk_type, 'SAFETY_STOCK_BREACH', 'WARNING_STOCK_BREACH', 'STOCK_POLICY_MISSING'), material_code, id
LIMIT #{offset}, #{pageSize}
